// TH14 synthetic appearance aliases (copied from transcribe/th14/touhou-bullets.ecl).
// native type 40 -> TH14_NOTE_YELLOW = target TH18 type 41 (row base 1008, colors 0-15)
// native type 42 -> TH14_REST        = target TH18 type 43 (row base 1040, colors 0-7)
// Synthetic mapping of base radii/color slots, not byte-identical original assets.
const TH14_NOTE_YELLOW: int = 1008;
const TH14_REST: int = 1040;

// th14_s4_mb2: TH14 v1.00b st04mbs2.ecl MBossB2 (source lines 121-168, route A SHOTTYPE 0/2/4).
// Source T0 is MBossB2's timerReset. The shell starts the segment at card frame 0, opens with
// 120 safe frames, then spawns the boss; the source's own 120 invuln + 60 charge waits follow,
// so both emitter asyncs start at source T180. Native slot-0 timeout is 1800 (setInterrupt at
// source line 147); emission stops there and MBossBDead is used only as the card's tail.

const TIME_LIMIT: int = 2424;         // 120 opening + 2300 window + 4 startup allowance
const OPENING_BUFFER: int = 120;

const SOURCE_TIMEOUT: int = 1800;     // source setInterrupt(0, 0, 1800, "MBossBDead")
const ENTRY_DELAY: int = 180;         // setInvuln(120) + wait(60) before the asyncs
const EMIT_SPAN: int = SOURCE_TIMEOUT - ENTRY_DELAY;   // 1620 frames of emission

// source moveLimit(0, 128, 280, 64): full width/height -> x in [-140,140], y in [96,160]
const LIMIT_X: fx = 140fx;
const LIMIT_Y0: fx = 96fx;
const LIMIT_Y1: fx = 160fx;

// source ANIM birth retreat is position -= 4*velocity; with etDist the net offset is
// etDist - 4*initial_speed (aim-modes birth-distance recipe).
const REST_BIRTH_DIST: fx = 4fx;      // 16 - 4*3.0
const NOTE_BIRTH_DIST: fx = 6.4fx;    // 16 - 4*2.4

// Source MBossB2_at EX chain: ANIM (approved spawn-stage omission), WAIT 40, then
// VELTIME(a=40, r=1.0, s=-999999 keeps angle): speed 3.0 -> 1.0 over 40 frames.
// WAIT expires and the next effect enters on the same tick, so the ramp's first update is
// source frame 40; the target STEP initializes on start and advances next frame, hence @39.
xformdef REST_SLOW {
    @39 add_speed(0fx);
    step_speed(1fx, 40);
}

// ---- source moveRand(60, 4, 0.4) movement, with the entry moveLimit applied per tick ----
// self int0 = next step count, self fx0/fx1 = logical unit direction.
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 {
        speed = (60 - k) as fx * 0.4fx / 60fx;
    }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -LIMIT_X { nx = -LIMIT_X; }
    if nx > LIMIT_X { nx = LIMIT_X; }
    if ny < LIMIT_Y0 { ny = LIMIT_Y0; }
    if ny > LIMIT_Y1 { ny = LIMIT_Y1; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_rand_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

sub move_rand_card() {
    // source 412 moveRand: one fixed direction per call, speed decays 0.4*(1-k/60).
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native +/-pi/2 guard, epsilon 0.05 rad = 522 BAM around -16384/16384
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_rand_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

// ---- source MBossB2_at (emitter 0): fixed ring, 32/48 ways, 3.0 speed, then VELTIME to 1.0 ----
async sub emit_rest() {
    var rank: int = global(GVAR_RANK);
    var ways: int = 48;
    var interval: int = 30;
    if rank == RANK_EASY {
        ways = 32;
        interval = 80;
    } else if rank == RANK_LUNATIC {
        interval = 25;
    }
    sh_reset(0);
    sh_sprite(0, TH14_REST, 1);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, ways, 1);
    sh_speed(0, 3fx, 0fx);            // etSpeed(3.0, 1.0) with one layer: 3.0; 1.0 is VELTIME target
    sh_dist(0, REST_BIRTH_DIST);
    sh_xform(0, REST_SLOW);
    // %A = %RANDRAD once, then +3.883222 rad per volley
    var base: angle = (rand(65536) - 32768) as angle;
    var elapsed: int = 0;
    while elapsed < EMIT_SPAN {
        sh_angle(0, base, 0deg);      // source etAngle(%A, 0)
        sh_fire(0);
        base = base + (40503 as angle);
        wait(interval);
        elapsed = elapsed + interval;
    }
}

// ---- source MBossB2_at2 (emitter 1): alternating-layer note ring, %A += 0.15708 rad ----
async sub emit_notes() {
    var rank: int = global(GVAR_RANK);
    var ways: int = 1;
    var layers: int = 1;
    var interval: int = 4;
    var half: angle = 0deg;
    var layer_step: angle = 0deg;
    if rank != RANK_EASY {
        // mode 10 with M=2: H = delta/2 = 5deg, layer sets are alpha-+5deg rings
        layers = 2;
        half = 910 as angle;
        layer_step = 1820 as angle;   // 0.17453292 rad = 10deg
        if rank == RANK_NORMAL {
            interval = 3;
        } else if rank == RANK_HARD {
            ways = 2;
            interval = 2;
        } else {
            ways = 3;
            interval = 2;
        }
    }
    sh_reset(1);
    sh_sprite(1, TH14_NOTE_YELLOW, 0);
    sh_ring(1, 1);
    sh_aim(1, 0);
    sh_count(1, ways, layers);
    sh_speed(1, 2.4fx, 0fx);
    sh_dist(1, NOTE_BIRTH_DIST);
    var k: int = 0;                   // source %A starts at 0.0
    var elapsed: int = 0;
    while elapsed < EMIT_SPAN {
        // 0.15708 rad = 9deg; keep the exact 1638.4 BAM step to avoid drift over 810 volleys
        sh_angle(1, ((k * 16384 / 10) as angle) - half, layer_step);
        sh_fire(1);
        k = k + 1;
        wait(interval);
        elapsed = elapsed + interval;
    }
}

// ---- default.ecl Ecl_EtBreak_ni 148-164: expanding circular clear, 16..636 by 10 ----
async sub et_break_ni() {
    var cx: fx = $self_x;
    var cy: fx = $self_y;
    var r: fx = 16fx;
    while r < 640fx {
        clear_bullets_at(cx, cy, r, 0);   // stars are presentation, omitted
        r = r + 10fx;
        wait(1);
    }
}

// ---- source MBossB2 body ----
async sub boss_main() {
    // MBossB entry state: hurtbox/hitbox 48,48 -> radius 24, body collision enabled.
    set_invuln(65535);                // no-DPS shell replaces source setInvuln(120)
    set_hitbox(24fx);
    set_hurtbox(24fx);
    // source line 132 etCancel(640) is the TIMEOUT entry path (previous slot-0 timeout);
    // this isolated card has no earlier bullets, but keep the entry closure.
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    wait(120);                        // source setInvuln(120); wait(120)
    wait(60);                         // source charge wait; asyncs start next tick (T180)
    spawn emit_rest();
    spawn emit_notes();

    var f0: fx = 0.017453fx;          // source %F0: flipped by the loop, not read in this segment
    // 10 full 160-frame move cycles = 1600 frames, then 20 frames into wait(60) when the
    // native 1800-frame slot-0 timer fires.
    for cycle in 0..10 {
        card_wait(60);
        f0 = -f0;
        card_wait(30);
        move_rand_card();
        card_wait(70);
    }
    card_wait(20);

    // MBossBDead timeout tail (source 368-395), no next attack.
    spawn et_break_ni();
    wait(120);
    move_to(60, -224fx, 64fx, EASE_QUAD_OUT);
    wait(60);
    // source delete(); delete() -> returning retires this boss silently
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 9000, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
